/**
 * Keeps the "current release notes" block in `README.md` in sync with the
 * CHANGELOG section of the version in `package.json`.
 *
 * Two consumers read the README: the repository hosts (Gitea and its GitHub
 * mirror render it) and the npm package page. Both should show the changes of
 * the released version instead of only a link, so the block is generated and
 * committed in the repository as part of the release, and re-generated by
 * `release.yml` right before `npm publish` (idempotent).
 *
 * `CHANGELOG.md` stays the single source of truth: never edit the block between
 * the markers by hand.
 *
 * Usage:
 *   node scripts/sync-readme-changelog.mjs          # rewrite README.md
 *   node scripts/sync-readme-changelog.mjs --check   # verify (ci.yml, npm run check)
 */

import { readFileSync, writeFileSync } from "node:fs";
import { changelogDate, changelogSection } from "./changelog-section.mjs";

const README = "README.md";
const CHANGELOG = "CHANGELOG.md";
const PACKAGE = "package.json";
const START = "<!-- changelog:start -->";
const END = "<!-- changelog:end -->";
const SCRIPT = "scripts/sync-readme-changelog.mjs";

function fail(message) {
  console.error(`::error::${message}`);
  process.exit(1);
}

const version = JSON.parse(readFileSync(PACKAGE, "utf8")).version;
const changelog = readFileSync(CHANGELOG, "utf8");
const readme = readFileSync(README, "utf8");

const section = changelogSection(changelog, version);
if (!section) fail(`${CHANGELOG} has no ## [${version}] section`);
const date = changelogDate(changelog, version);

// Markers must be unique and in order.
const start = readme.indexOf(START);
const end = readme.indexOf(END);
if (start === -1 || end === -1 || end < start) {
  fail(`${README} needs the ${START} / ${END} markers around the release-notes block`);
}
if (readme.indexOf(START, start + 1) !== -1 || readme.indexOf(END, end + 1) !== -1) {
  fail(`${README} has duplicate ${START}/${END} markers`);
}

const block = [
  `<!-- Generated by ${SCRIPT}; edit ${CHANGELOG}, not this block. -->`,
  `**${version}${date ? ` - ${date}` : ""}**`,
  "",
  section,
  "",
  `Full history and all versions: [${CHANGELOG}](./${CHANGELOG})`,
].join("\n");

if (process.argv.includes("--check")) {
  const current = readme.slice(start + START.length, end).trim();
  if (current !== block) {
    fail(`${README} release-notes block is stale - run "npm run readme" and commit it`);
  }
  console.log(`${README} release-notes block matches ${version}.`);
  process.exit(0);
}

writeFileSync(
  README,
  readme.slice(0, start) + `${START}\n${block}\n${END}` + readme.slice(end + END.length),
  "utf8",
);
console.log(`Synced the ${version} release notes into ${README}.`);
